pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and a boolean that decides whether we attempt a second call in the same block
    function testFuzz_property(address caller, bool secondCallSameBlock) public {
        // admissible domain: caller should be a non-zero address and not the test contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund the caller so it can send 10 ether
        uint256 amt = 10 ether;
        vm.deal(caller, amt * 2);

        // First call: should succeed and set pastBlockTime to block.timestamp
        vm.prank(caller);
        c.f{value: amt}();
        uint256 t1 = c.pastBlockTime();

        // Now either perform a second call in the same block (no warp/roll) or in the next block
        bool ok;
        vm.prank(caller);
        if (secondCallSameBlock) {
            // second call in same block: in correct contract this MUST revert because timestamp would not be > t1
            try c.f{value: amt}() {
                ok = true;
            } catch {
                ok = false;
            }
            // For the correct contract, the second call in same block must revert (ok == false).
            // For the mutant, it may succeed (ok == true) because it allows >=.
            // We assert that pastBlockTime strictly increased after the successful sequence of calls.
            if (ok) {
                // if mutant allowed success in same block, pastBlockTime would be unchanged; capture it
                uint256 t2 = c.pastBlockTime();
                // The universal property: after any successful sequence of fallback calls sending 10 ether,
                // each successful call sets pastBlockTime to a strictly larger value than before.
                // So t2 must be > t1. This holds for the reference for ALL inputs; the mutant can violate it.
                assertTrue(t2 > t1);
            } else {
                // call reverted as expected for reference; property still holds vacuously because no second success
                // We assert the invariant that after the single successful call, pastBlockTime == t1 (already read).
                // To keep exactly one assertTrue overall, we assert the universal property by verifying that
                // when a second call failed (ok == false), pastBlockTime remains as set by the first call and
                // there was no successful second call that would need to increase it.
                // Represent this by asserting that ok == false OR (pastBlockTime > t1). Since ok==false here,
                // the following assertion will hold for the correct contract for all inputs.
                assertTrue(ok == false || c.pastBlockTime() > t1);
            }
        } else {
            // second call in a later block: advance time to ensure block.timestamp > t1
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);
            vm.prank(caller);
            // second call should succeed on both reference and mutant, and must strictly increase pastBlockTime
            c.f{value: amt}();
            uint256 t2 = c.pastBlockTime();
            assertTrue(t2 > t1);
        }
    }
}

